 problem('projection','angle','Project using magnitude and included angle','A <strong>200 N</strong> force makes an angle of <strong>120° with the positive axis</strong>. Find the signed projection.',[scalar('Apply the cosine projection','The angle is between the force and the positive axis, not necessarily +x.','Signed projection (N)',-100,'Faxis = |F| cos θ','Use the given magnitude and included angle.',[row('Substitute in degree mode.','Faxis = 200 cos(120°) = −100 N'),row('The obtuse angle produces a negative projection, directed against the positive axis.')])],forces(arrow(zero,[-100,173.20508,0],'F'),arrow(zero,[200,0,0],'positive axis','#efbd77',true)));
 const pf=[-90,40,-120],pd=[3,4,12],pu=unit(pd);problem('projection','negative-3d','Signed 3D projection onto a cable axis','Project <strong>F = (−90, 40, −120) N</strong> onto the positive axis from <strong>A = (0, 0, 0) m</strong> to <strong>B = (3, 4, 12) m</strong>.',[displacement(zero,pd),normalize(pd),projection(pf,pu)],{...momentGraph(zero,pf,pd),note:'Axis coordinates use metres. The force arrow shows direction only; its magnitude and components are given in the question.'});
 const ff=[100,-50,200],du=[2,1,2],uu=unit(du),parallel=scale(uu,M.dot(ff,uu)),perp=sub(ff,parallel);problem('projection','perpendicular','3D parallel and perpendicular force vectors','Split <strong>F = (100, −50, 200) N</strong> into parts parallel and perpendicular to <strong>d = (2, 1, 2) m</strong>.',[normalize(du),projection(ff,uu),vector('Build the parallel vector','The scalar projection needs the unit axis to restore Cartesian direction.','Fparallel',parallel,'N','Fparallel = Faxis u','Use your checked scalar and unit vector.',[row('Multiply the scalar into every unit component.',...axes.map((a,i)=>'Fparallel'+a+' = '+round(M.dot(ff,uu))+'('+round(uu[i])+') = '+round(parallel[i])+' N'))]),vector('Subtract the perpendicular remainder','The two parts must sum to the original force.','Fperp',perp,'N','Fperp = F − Fparallel','Use the original force and checked parallel components.',[row('Subtract component by component.',...axes.map((a,i)=>'Fperp'+a+' = '+ff[i]+' − ('+round(parallel[i])+') = '+round(perp[i])+' N')),row('Check orthogonality.','Fperp · u = 0')])],forces(arrow(zero,ff,'F'),arrow(zero,scale(uu,200),'positive axis','#efbd77',true)));
 const vf=[60,80,0],vd=[0,1,1];problem('projection','included-angle','Find the 3D angle between force and axis','Find the angle between <strong>F = (60, 80, 0) N</strong> and positive direction <strong>d = (0, 1, 1) m</strong>.',[normalize(vd),magnitude(vf,'F','N'),projection(vf,unit(vd)),scalar('Recover the included angle','Divide the signed projection by force magnitude to obtain cosine.','Included angle (degrees)',Math.acos(M.dot(vf,unit(vd))/100)*180/Math.PI,'θ = cos⁻¹(Faxis/|F|)','Use your checked signed projection and force magnitude.',[row('The dot-product identity relates projection to included angle.','cos θ = 56.5685/100'),row('Use inverse cosine in degree mode.','θ = cos⁻¹(0.565685) = 55.5501°')])],forces(arrow(zero,vf,'F'),arrow(zero,scale(unit(vd),100),'positive axis','#efbd77',true)));
 // Moments: scalar planar formula, spatial cross product, inverse force, perpendicular arm.
 problem('moments','scalar','Planar scalar moment with signs','At <strong>P = (3, 2, 0) m</strong>, force <strong>F = (40, −50, 0) N</strong> acts. Find Mz about O.',[displacement(zero,[3,2,0],"rOP","O","P"),scalar('Calculate the planar moment','Use the signed force components; +z is counterclockwise viewed from +z.','Mz (N·m)',-230,'Mz = rx Fy − ry Fx','Use checked r and given F.',[row('Each force component contributes its own signed turning effect.','Mz = 3(−50) − 2(40) = −150 − 80 = −230 N·m'),row('Negative z indicates clockwise rotation viewed from +z.')])],momentGraph([3,2,0],[40,-50,0]));
 const mp=[2,-1,3],mf=[30,80,-20],mv=M.cross(mp,mf);problem('moments','3d','Full 3D point moment','At <strong>P = (2, −1, 3) m</strong>, force <strong>F = (30, 80, −20) N</strong> acts. Find the moment about O and its magnitude.',[displacement(zero,mp,"rOP","O","P"),crossStep(mp,mf),magnitude(mv,'M','N·m')],momentGraph(mp,mf));
